# set template test shape relative from positions r3 c7; r4 c6,c8; r5 c5,c6,c8
T={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
def d4(S):
    out=[]
    for refl in [False,True]:
        a={(r, -c if refl else c) for r,c in S}
        for k in range(4):
            # normalized rotate clockwise: (r,c)->(c,-r)
            pts=a.copy()
            for _ in range(k): pts={(c,-r) for r,c in pts}
            mr=min(r for r,c in pts); mc=min(c for r,c in pts)
            out.append(frozenset((r-mr,c-mc) for r,c in pts))
    return list(dict.fromkeys(out))
shapes=d4(T)
print(len(shapes), [len(s) for s in shapes])
def placements(seeds):
    result=[]
    for shape in shapes:
        for sr,sc in seeds:
            for tr,tc in shape:
                dr,dc=sr-tr,sc-tc
                pts={(r+dr,c+dc) for r,c in shape}
                if set(seeds)<=pts:
                    result.append((shape,dr,dc,pts))
    # dedupe placements
    uniq={frozenset(p[3]):p for p in result}
    return list(uniq.values())
